<?php
namespace App\Console\Commands;use Illuminate\Console\Command;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\DB;class SystemHealthCheck extends Command{protected$signature='system:health';protected$description='Kontrollerer database, skrivbar lagring og køforsinkelser';public function handle():int{$errors=[];try{DB::select('select 1');}catch(\Throwable$e){$errors[]='database';}$probe=storage_path('framework/cache/health-'.getmypid());if(@file_put_contents($probe,'ok')===false)$errors[]='storage';else@unlink($probe);$oldMessages=DB::table('outbound_messages')->where('status','queued')->where('scheduled_at','<',now()->subMinutes(10))->count();$oldInvoices=DB::table('invoice_exports')->where('status','queued')->where('queued_at','<',now()->subMinutes(10))->count();if($oldMessages)$errors[]='message_queue:'.$oldMessages;if($oldInvoices)$errors[]='accounting_queue:'.$oldInvoices;$payload=['checked_at'=>now()->toIso8601String(),'healthy'=>$errors===[],'issues'=>$errors];Cache::put('system.health',$payload,now()->addMinutes(10));$this->line(json_encode($payload));return$errors===[]?self::SUCCESS:self::FAILURE;}}
